using System;using System.Text;using System.Globalization;
namespace Frociart {
    // Length-prefixed UTF-16 fields preserve unfinished form input, including invalid template syntax.
    internal sealed class FlowTemplateDraft {
        internal readonly string Name,Base,Extension,Instructions,Body;internal readonly bool CaseSensitive;
        internal FlowTemplateDraft(string name,string language,string extension,string instructions,string body,bool sensitive=true){Name=name??"";Base=language??"";Extension=extension??"";Instructions=instructions??"";Body=body??"";CaseSensitive=sensitive;}
        internal FlowTemplateDraft(FlowCodeTemplate definition):this(definition.Name,definition.Base,definition.Extension,definition.Instructions,definition.Body,definition.CaseSensitive){}
        internal FlowCodeTemplate Definition(){return FlowCodeTemplate.Create(Name,Base,Extension,Instructions,Body,CaseSensitive);}
        internal string Encode(){var fields=new[]{Name,Base,Extension,Instructions,Body,CaseSensitive?"true":"false"};var limits=new[]{80,64,16,1000,262144,5};for(int i=0;i<fields.Length;i++)if(fields[i].Length>limits[i])throw new ArgumentException("La bozza del modello supera il limite.");var b=new StringBuilder("FrociartTemplateDraft1\n");foreach(string field in new[]{Name,Base,Extension,Instructions,Body,CaseSensitive?"true":"false"})b.Append(field.Length.ToString(CultureInfo.InvariantCulture)).Append('\n').Append(field);string result=b.ToString();if(result.Length>FlowTemplateStore.MaxDraftCharacters)throw new ArgumentException("La bozza del modello supera il limite.");return result;}
        internal static FlowTemplateDraft Decode(string text){const string magic="FrociartTemplateDraft1\n";if(text==null||text.Length>FlowTemplateStore.MaxDraftCharacters||!text.StartsWith(magic,StringComparison.Ordinal))throw new ArgumentException("Formato della bozza del modello non valido.");int at=magic.Length;var values=new string[6];var limits=new[]{80,64,16,1000,262144,5};for(int i=0;i<values.Length;i++){int end=text.IndexOf('\n',at),length;if(end<0||end-at>6||end==at||!Int32.TryParse(text.Substring(at,end-at),NumberStyles.None,CultureInfo.InvariantCulture,out length)||length>limits[i]||length>text.Length-end-1)throw new ArgumentException("La bozza del modello è incompleta o troppo lunga.");at=end+1;values[i]=text.Substring(at,length);at+=length;}if(at!=text.Length||values[5]!="true"&&values[5]!="false")throw new ArgumentException("La bozza del modello contiene dati non validi.");return new FlowTemplateDraft(values[0],values[1],values[2],values[3],values[4],values[5]=="true");}
    }
}
